/** True when `value` is a package state, from `PACKAGE_STATES`. */
export const isPackageState = (value: unknown): value is PackageState =>
  PACKAGE_STATES.includes(value as PackageState);

/** True when `value` is a change state, from `CHANGE_STATES`. */
export const isChangeState = (value: unknown): value is ChangeState =>
  CHANGE_STATES.includes(value as ChangeState);

/** True when the table `table` has a transition from `from` to `to` by `command`. */
export const hasTransition = <S extends string>(
  table: readonly Transition<S>[],
  step: Transition<S>,
): boolean =>
  table.some(
    (t) =>
      t.from === step.from && t.to === step.to && t.command === step.command,
  );

